package ace

import("encoding/json";"testing")

func TestExecutableAcquisitionMethodIsSerializableAndComposable(t *testing.T){l:=NewSearchLibrary();m:=ExecutableAcquisitionMethod{ID:"m-test",Instructions:[]MethodInstruction{{Op:"search",Arg:"search:branching"}},Verifier:"independent-heldout",Version:1};if err:=l.RegisterMethod(m);err!=nil{t.Fatal(err)};b,err:=json.Marshal(m);if err!=nil{t.Fatal(err)};var q ExecutableAcquisitionMethod;if err=json.Unmarshal(b,&q);err!=nil{t.Fatal(err)};if q.ID!=m.ID||len(q.Instructions)!=1{t.Fatalf("round-trip mismatch: %#v",q)};task:=Task{ID:"self-ext-test",Goal:"conditional",Requirements:[]string{"x"},Structure:[]string{"scalar","conditional"},Budget:ResourceVector{Compute:100,Memory:100,TimeMS:5000,ExperimentBudget:20}};cases:=[]ProgramTestCase{methodInputOutputExample(-2,0),methodInputOutputExample(3,1)};spec,err:=GeneralCapabilitySpecification(task,cases);if err!=nil{t.Fatal(err)};composed:=ExecutableAcquisitionMethod{ID:"m-compose",Instructions:[]MethodInstruction{{Op:"use",Arg:m.ID},{Op:"dedupe"}},Verifier:"independent-heldout",Version:2};ok,_,err:=VerifyExecutableMethod(l,composed,spec,cases);if err!=nil{t.Fatal(err)};if !ok{t.Fatal("composed persisted method failed independent behavioral check")}}

func TestSelfExtensibleCapabilityProbe(t *testing.T){r,err:=RunSelfExtensibleExperiment();if err!=nil{t.Fatal(err)};if !r.T1Solved||!r.T2Solved||!r.M1Verified||!r.M1UsedByB1||!r.T3Solved||!r.T4Solved||!r.M2Verified||!r.T5Solved{t.Fatalf("self-extensible probe failed: %#v",r)};if !r.LearnedAbstraction{t.Fatalf("no repeated executable abstraction learned: %#v",r)};if r.M1.ID==r.M2.ID{t.Fatal("M1 and M2 must be distinct artifacts")}}
